-- ============================================
-- LUMA — Thème 13 (Conférence/Networking) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"stranger": "l''inconnu(e)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You spot someone standing alone near the bar, glancing occasionally at their phone.)", "text_fr": "(Vous repérez quelqu''un debout seul près du bar, regardant occasionnellement son téléphone.)", "choices": [{"text": "Hi there, mind if I join you? This event is quite the crowd.", "text_fr": "Salut, ça vous dérange si je me joins à vous ? Cet événement a du monde.", "next": "n2"}, {"text": "Hi! I don''t think we''ve met — I''m [name]. What brings you here tonight?", "text_fr": "Salut ! Je pense qu''on s''est pas rencontrés — je suis [nom]. Qu''est-ce qui vous amène ce soir ?", "next": "n2b"}]}, "n2": {"speaker": "stranger", "text": "Oh, please do! Yeah, I don''t know many people here yet, to be honest.", "text_fr": "Oh, je vous en prie ! Ouais, je connais pas beaucoup de monde ici encore, honnêtement.", "choices": [{"text": "Same here, actually. What field are you in?", "text_fr": "Pareil pour moi, en fait. Vous êtes dans quel domaine ?", "next": "n3"}]}, "n2b": {"speaker": "stranger", "text": "I''m in marketing, actually here scouting for potential partnerships. You?", "text_fr": "Je suis dans le marketing, en fait je suis ici pour repérer des partenariats potentiels. Et vous ?", "choices": [{"text": "I work in software development — nice to meet a fellow networker.", "text_fr": "Je travaille en développement logiciel — ravi de rencontrer un autre habitué du networking.", "next": "n3"}]}, "n3": {"speaker": "stranger", "text": "Nice to meet you! This is actually my first time at this particular conference.", "text_fr": "Ravi de vous rencontrer ! C''est en fait ma première fois à cette conférence en particulier.", "choices": [{"text": "Mine too! So far, what''s caught your interest the most?", "text_fr": "La mienne aussi ! Jusqu''ici, qu''est-ce qui a le plus attiré votre attention ?", "next": "n4"}]}, "n4": {"speaker": "stranger", "text": "Honestly, the keynote this morning was fantastic. Did you catch it?", "text_fr": "Honnêtement, le discours d''ouverture ce matin était fantastique. Vous l''avez vu ?", "choices": [{"text": "I did! The part about industry trends really stuck with me.", "text_fr": "Oui ! La partie sur les tendances de l''industrie m''a vraiment marqué.", "next": "n5"}]}, "n5": {"speaker": "stranger", "text": "Same here. It''s refreshing to talk to someone who was actually paying attention!", "text_fr": "Pareil pour moi. C''est rafraîchissant de parler à quelqu''un qui était vraiment attentif !", "choices": [{"text": "Ha, well, this has been a great conversation. Should we exchange contacts?", "text_fr": "Ha, bon, c''était une super conversation. On devrait échanger nos contacts ?", "next": "end_connected"}]}, "end_connected": {"speaker": "stranger", "text": "Absolutely, I''d love to stay in touch after tonight.", "text_fr": "Absolument, j''aimerais rester en contact après ce soir.", "end": true, "ending_label": "Première conversation networking réussie 🥂🤝"}}}'::jsonb, is_playable = true
where title = 'Se présenter à un inconnu lors d''''un cocktail'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"colleague": "votre interlocuteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "colleague", "text": "This conversation''s been great! I''d love to keep in touch after tonight.", "text_fr": "Cette conversation était super ! J''aimerais rester en contact après ce soir.", "choices": [{"text": "Absolutely, here''s my card — feel free to reach out anytime.", "text_fr": "Absolument, voici ma carte — n''hésitez pas à me contacter quand vous voulez.", "next": "n2"}, {"text": "Definitely! Do you have a card, or should we connect on LinkedIn instead?", "text_fr": "Définitivement ! Vous avez une carte, ou on se connecte plutôt sur LinkedIn ?", "next": "n2b"}]}, "n2": {"speaker": "colleague", "text": "Perfect, here''s mine as well. I''ll definitely follow up next week.", "text_fr": "Parfait, voici la mienne aussi. Je vais définitivement relancer la semaine prochaine.", "choices": [{"text": "Sounds great, I''ll look forward to hearing from you.", "text_fr": "Ça marche, j''attendrai votre message avec impatience.", "next": "n3"}]}, "n2b": {"speaker": "colleague", "text": "LinkedIn works great for me too, let''s connect right now actually.", "text_fr": "LinkedIn me va très bien aussi, connectons-nous tout de suite en fait.", "choices": [{"text": "Perfect, let me pull it up on my phone.", "text_fr": "Parfait, laissez-moi l''ouvrir sur mon téléphone.", "next": "n3"}]}, "n3": {"speaker": "colleague", "text": "Great, all set! It was genuinely a pleasure talking with you tonight.", "text_fr": "Super, c''est fait ! Ce fut un vrai plaisir de discuter avec vous ce soir.", "choices": [{"text": "Likewise, I hope we can collaborate on something in the future.", "text_fr": "Pareillement, j''espère qu''on pourra collaborer sur quelque chose à l''avenir.", "next": "end_exchanged"}]}, "end_exchanged": {"speaker": "colleague", "text": "I''d really like that. Enjoy the rest of the event!", "text_fr": "J''aimerais vraiment ça. Profitez du reste de l''événement !", "end": true, "ending_label": "Contact professionnel échangé avec succès 📇✅"}}}'::jsonb, is_playable = true
where title = 'Échanger une carte de visite'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
